let file = """{"version":3,"file":"Load3dUtils-CUFiVR0e.js","names":[],"sources":["../../src/services/uploadTempFile.ts","../../src/extensions/core/load3d/Load3dUtils.ts"],"sourcesContent":["import type { UploadImageResponse } from '@comfyorg/ingest-types'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { t } from '@/i18n'\nimport { api } from '@/scripts/api'\n\ntype TempFileUpload =\n  | { ok: true; file: UploadImageResponse }\n  | { ok: false; reason: string }\n\nexport async function uploadTempFile(\n  file: File,\n  subfolder: string\n): Promise<TempFileUpload> {\n  const body = new FormData()\n  body.append('image', file)\n  body.append('subfolder', subfolder)\n  body.append('type', 'temp')\n\n  const resp = await api.fetchApi('/upload/image', { method: 'POST', body })\n  if (resp.status !== 200) {\n    const reason = `${resp.status} - ${resp.statusText}`\n    useToast().warning(t('g.uploadFailed', { reason }))\n    return { ok: false, reason }\n  }\n  return { file: await resp.json(), ok: true }\n}\n","import { t } from '@/i18n'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { uploadTempFile } from '@/services/uploadTempFile'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nclass Load3dUtils {\n  static async uploadTempImage(\n    imageData: string,\n    prefix: string,\n    fileType: string = 'png'\n  ) {\n    const blob = await fetch(imageData).then((r) => r.blob())\n    const name = `${prefix}_${Date.now()}.${fileType}`\n    const file = new File([blob], name, {\n      type: fileType === 'mp4' ? 'video/mp4' : 'image/png'\n    })\n\n    const upload = await uploadTempFile(file, 'threed')\n    if (!upload.ok)\n      throw new Error(`Error uploading temp file: ${upload.reason}`)\n    return upload.file\n  }\n\n  static readonly MAX_UPLOAD_SIZE_MB = 100\n\n  static async uploadFile(file: File, subfolder: string) {\n    let uploadPath\n\n    const fileSizeMB = file.size / 1024 / 1024\n    if (fileSizeMB > this.MAX_UPLOAD_SIZE_MB) {\n      const message = t('toastMessages.fileTooLarge', {\n        size: fileSizeMB.toFixed(1),\n        maxSize: this.MAX_UPLOAD_SIZE_MB\n      })\n      console.warn(\n        '[Load3D] uploadFile: file too large',\n        fileSizeMB.toFixed(2),\n        'MB'\n      )\n      useToast().warning(message)\n      return undefined\n    }\n\n    try {\n      const body = new FormData()\n      body.append('image', file)\n\n      body.append('subfolder', subfolder)\n\n      const resp = await api.fetchApi('/upload/image', {\n        method: 'POST',\n        body\n      })\n\n      if (resp.status === 200) {\n        const data = await resp.json()\n        let path = data.name\n\n        if (data.subfolder) {\n          path = data.subfolder + '/' + path\n        }\n\n        uploadPath = path\n      } else {\n        useToast().warning(\n          t('g.uploadFailed', {\n            reason: `${resp.status} - ${resp.statusText}`\n          })\n        )\n      }\n    } catch (error) {\n      console.error('[Load3D] uploadFile: exception', error)\n      useToast().warning(\n        t('g.uploadFailed', {\n          reason: getErrorMessage(error) ?? t('g.unknownError')\n        })\n      )\n    }\n\n    return uploadPath\n  }\n\n  static getFilenameExtension(url: string): string | undefined {\n    const queryString = url.split('?')[1]\n    if (queryString) {\n      const filename = new URLSearchParams(queryString).get('filename')\n      if (filename) return filename.split('.').pop()?.toLowerCase()\n    }\n    return url.split('?')[0].split('.').pop()?.toLowerCase()\n  }\n\n  static splitFilePath(path: string): [string, string] {\n    const folder_separator = path.lastIndexOf('/')\n    if (folder_separator === -1) {\n      return ['', path]\n    }\n    return [\n      path.substring(0, folder_separator),\n      path.substring(folder_separator + 1)\n    ]\n  }\n\n  static getResourceURL(\n    subfolder: string,\n    filename: string,\n    type: string = 'input'\n  ): string {\n    const params = [\n      'filename=' + encodeURIComponent(filename),\n      'type=' + type,\n      'subfolder=' + subfolder,\n      useApp().getRandParam().substring(1)\n    ].join('&')\n\n    return `/view?${params}`\n  }\n\n  static async uploadMultipleFiles(files: FileList, subfolder: string = '3d') {\n    const uploadPromises = Array.from(files).map((file) =>\n      this.uploadFile(file, subfolder)\n    )\n\n    await Promise.all(uploadPromises)\n  }\n\n  static mapSceneLightIntensityToHdri(\n    sceneIntensity: number,\n    sceneMin: number,\n    sceneMax: number\n  ): number {\n    const span = sceneMax - sceneMin\n    const t = span > 0 ? (sceneIntensity - sceneMin) / span : 0\n    const clampedT = Math.min(1, Math.max(0, t))\n    const mapped = clampedT * 5\n    const minHdri = 0.25\n    return Math.min(5, Math.max(minHdri, mapped))\n  }\n}\n\nexport default Load3dUtils\n"],"mappings":"wPAUA,eAAsB,eACpB,EACA,EACyB,CACzB,IAAM,EAAO,IAAI,SACjB,EAAK,OAAO,QAAS,CAAI,EACzB,EAAK,OAAO,YAAa,CAAS,EAClC,EAAK,OAAO,OAAQ,MAAM,EAE1B,IAAM,EAAO,MAAM,EAAI,SAAS,gBAAiB,CAAE,OAAQ,OAAQ,MAAK,CAAC,EACzE,GAAI,EAAK,SAAW,IAAK,CACvB,IAAM,EAAS,GAAG,EAAK,OAAO,KAAK,EAAK,aAExC,OADA,EAAS,CAAC,CAAC,QAAQ,EAAE,iBAAkB,CAAE,QAAO,CAAC,CAAC,EAC3C,CAAE,GAAI,GAAO,QAAO,CAC7B,CACA,MAAO,CAAE,KAAM,MAAM,EAAK,KAAK,EAAG,GAAI,EAAK,CAC7C,CCnBA,IAAM,YAAN,KAAkB,CAChB,aAAa,gBACX,EACA,EACA,EAAmB,MACnB,CACA,IAAM,EAAO,MAAM,MAAM,CAAS,CAAC,CAAC,KAAM,GAAM,EAAE,KAAK,CAAC,EAClD,EAAO,GAAG,EAAO,GAAG,KAAK,IAAI,EAAE,GAAG,IAKlC,EAAS,MAAM,eAAe,IAJnB,KAAK,CAAC,CAAI,EAAG,EAAM,CAClC,KAAM,IAAa,MAAQ,YAAc,WAC3C,CAEoC,EAAM,QAAQ,EAClD,GAAI,CAAC,EAAO,GACV,MAAU,MAAM,8BAA8B,EAAO,QAAQ,EAC/D,OAAO,EAAO,IAChB,CAEA,OAAgB,mBAAqB,IAErC,aAAa,WAAW,EAAY,EAAmB,CACrD,IAAI,EAEE,EAAa,EAAK,KAAO,KAAO,KACtC,GAAI,EAAa,KAAK,mBAAoB,CACxC,IAAM,EAAU,EAAE,6BAA8B,CAC9C,KAAM,EAAW,QAAQ,CAAC,EAC1B,QAAS,KAAK,kBAChB,CAAC,EACD,QAAQ,KACN,sCACA,EAAW,QAAQ,CAAC,E